17	package org.springframework.samples.petclinic.rest.validation;
18	
19	import java.time.LocalDate;
20	import java.util.Locale;
21	
22	import org.springframework.samples.petclinic.model.FiscalYear;
23	
24	/**
25	 * Derives an owner's member id, the single identifier that unifies the former customer code and
26	 * membership number. It is formatted {@code <REGION><FY><HASH8><CHK>} where:
27	 * <ul>
28	 *   <li>REGION is the owner's region code (derived from the postcode, see
29	 *       {@link org.springframework.samples.petclinic.model.RegionResolver RegionResolver});</li>
30	 *   <li>FY is the two last digits, zero-padded, of the fiscal year of the registration date (the
31	 *       same fiscal year exposed as the {@code FY<YY>} label);</li>
32	 *   <li>HASH8 is the first eight upper-case hexadecimal characters of the SHA-256 digest of the
33	 *       owner's normalized telephone concatenated with the last name — the region-and-hash
34	 *       identity's hash segment;</li>
35	 *   <li>CHK is a single Luhn check digit computed over the digits of {@code <REGION><FY><HASH8>}.</li>
36	 * </ul>
37	 * For example {@code NSW261A2B3C4D5}. The id carries no sequence number, so it is stable for a given
38	 * region, fiscal year and (telephone, last name) pair.
39	 */
40	public final class MemberIdGenerator {
41	
42	    /** Number of leading hex characters of the SHA-256 digest kept as the id's hash segment. */
43	    private static final int HASH_LENGTH = 8;
44	
45	    private MemberIdGenerator() {
46	    }
47	
48	    /**
49	     * Builds the member id for a new owner.
50	     *
51	     * @param region              the owner's region code
52	     * @param normalizedTelephone the owner's telephone in its normalized storage form
53	     * @param lastName            the owner's last name
54	     * @param registrationDate    the owner's registration date
55	     * @return the member id, e.g. {@code "NSW261A2B3C4D5"}
56	     */
57	    public static String generate(String region, String normalizedTelephone, String lastName,
58	                                  LocalDate registrationDate) {
59	        String hash8 = Sha256.hex(orEmpty(normalizedTelephone) + orEmpty(lastName))
60	            .substring(0, HASH_LENGTH).toUpperCase(Locale.ROOT);
61	        String fy = String.format("%02d", FiscalYear.of(registrationDate) % 100);
62	        String base = region + fy + hash8;
63	        return base + LuhnCheckDigit.of(base);
64	    }
65	
66	    /**
67	     * Return the REGION segment of a member id: its leading run of non-digit characters, since the
68	     * region code is alphabetic and the following FY segment always begins with a digit.
69	     *
70	     * @param memberId a member id produced by {@link #generate}
71	     * @return the region segment
72	     */
73	    public static String regionOf(String memberId) {
74	        int end = 0;
75	        while (end < memberId.length() && !Character.isDigit(memberId.charAt(end))) {
76	            end++;
77	        }
78	        return memberId.substring(0, end);
79	    }
80	
81	    private static String orEmpty(String value) {
82	        return value == null ? "" : value;
83	    }
84	}
