31	import org.springframework.samples.petclinic.model.Pet;
32	import org.springframework.samples.petclinic.model.Visit;
33	import org.springframework.samples.petclinic.model.BusinessDayAdjuster;
34	import org.springframework.samples.petclinic.model.RegionResolver;
35	import org.springframework.samples.petclinic.rest.api.OwnersApi;
36	import org.springframework.samples.petclinic.rest.audit.OwnerAuditLogger;
37	import org.springframework.samples.petclinic.rest.notification.WelcomeNotifier;
38	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
39	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.PetDto;
41	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
42	import org.springframework.samples.petclinic.rest.dto.VisitDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
44	import org.springframework.samples.petclinic.rest.idempotency.IdempotentOwnerCreationStore;
45	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
46	import org.springframework.samples.petclinic.rest.validation.CityOwnerCapacityValidator;
47	import org.springframework.samples.petclinic.rest.validation.DailyRegistrationCapacityValidator;
48	import org.springframework.samples.petclinic.rest.validation.DisposableEmailDomainValidator;
49	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
50	import org.springframework.samples.petclinic.rest.validation.HouseholdDuplicateValidator;
51	import org.springframework.samples.petclinic.rest.validation.HouseholdKey;
52	import org.springframework.samples.petclinic.rest.validation.HouseholdMembershipLevelCap;
53	import org.springframework.samples.petclinic.rest.validation.HouseholdSizeCounter;
54	import org.springframework.samples.petclinic.rest.validation.MemberIdDeduplicator;
55	import org.springframework.samples.petclinic.rest.validation.MemberIdGenerator;
56	import org.springframework.samples.petclinic.rest.validation.OwnerFieldsValidator;
57	import org.springframework.samples.petclinic.rest.validation.NamesakeCounter;
58	import org.springframework.samples.petclinic.rest.validation.PossibleDuplicateOwnerDetector;
59	import org.springframework.samples.petclinic.rest.validation.PostcodeValidator;
60	import org.springframework.samples.petclinic.rest.validation.RegistrationDateValidator;
61	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
62	import org.springframework.samples.petclinic.service.ClinicService;
63	import org.springframework.security.access.prepost.PreAuthorize;
64	import org.springframework.web.bind.annotation.CrossOrigin;
65	import org.springframework.web.bind.annotation.RequestMapping;
66	import org.springframework.web.bind.annotation.RestController;
67	import org.springframework.web.util.UriComponentsBuilder;
68	
69	import jakarta.transaction.Transactional;
70	
71	/**
72	 * @author Vitaliy Fedoriv
73	 */
74	
75	@RestController
76	@CrossOrigin(exposedHeaders = "errors, content-type")
77	@RequestMapping("/api")
78	public class OwnerRestControllerV1 implements OwnersApi {
79	
80	    private final ClinicService clinicService;
81	
82	    private final OwnerMapper ownerMapper;
83	
84	    private final PetMapper petMapper;
85	
86	    private final VisitMapper visitMapper;
87	
88	    private final HouseholdDuplicateValidator householdDuplicateValidator;
89	
90	    private final PossibleDuplicateOwnerDetector possibleDuplicateOwnerDetector;
91	
92	    private final NamesakeCounter namesakeCounter;
93	
94	    private final HouseholdSizeCounter householdSizeCounter;
95	
96	    private final HouseholdMembershipLevelCap householdMembershipLevelCap;
97	
98	    private final CityOwnerCapacityValidator cityOwnerCapacityValidator;
99	
100	    private final DailyRegistrationCapacityValidator dailyRegistrationCapacityValidator;
101	
102	    private final OwnerAuditLogger ownerAuditLogger;
103	
104	    private final WelcomeNotifier welcomeNotifier;
105	
106	    private final MemberIdDeduplicator memberIdDeduplicator;
107	
108	    private final IdempotentOwnerCreationStore idempotentOwnerCreationStore;
109	
110	    public OwnerRestControllerV1(ClinicService clinicService,
111	                                 OwnerMapper ownerMapper,
112	                                 PetMapper petMapper,
113	                                 VisitMapper visitMapper,
114	                                 HouseholdDuplicateValidator householdDuplicateValidator,
115	                                 PossibleDuplicateOwnerDetector possibleDuplicateOwnerDetector,
116	                                 NamesakeCounter namesakeCounter,
117	                                 HouseholdSizeCounter householdSizeCounter,
118	                                 HouseholdMembershipLevelCap householdMembershipLevelCap,
119	                                 CityOwnerCapacityValidator cityOwnerCapacityValidator,
120	                                 DailyRegistrationCapacityValidator dailyRegistrationCapacityValidator,
121	                                 OwnerAuditLogger ownerAuditLogger,
122	                                 WelcomeNotifier welcomeNotifier,
123	                                 MemberIdDeduplicator memberIdDeduplicator,
124	                                 IdempotentOwnerCreationStore idempotentOwnerCreationStore) {
125	        this.clinicService = clinicService;
126	        this.ownerMapper = ownerMapper;
127	        this.petMapper = petMapper;
128	        this.visitMapper = visitMapper;
129	        this.householdDuplicateValidator = householdDuplicateValidator;
130	        this.possibleDuplicateOwnerDetector = possibleDuplicateOwnerDetector;
131	        this.namesakeCounter = namesakeCounter;
132	        this.householdSizeCounter = householdSizeCounter;
133	        this.householdMembershipLevelCap = householdMembershipLevelCap;
134	        this.cityOwnerCapacityValidator = cityOwnerCapacityValidator;
135	        this.dailyRegistrationCapacityValidator = dailyRegistrationCapacityValidator;
136	        this.ownerAuditLogger = ownerAuditLogger;
137	        this.welcomeNotifier = welcomeNotifier;
138	        this.memberIdDeduplicator = memberIdDeduplicator;
139	        this.idempotentOwnerCreationStore = idempotentOwnerCreationStore;
140	    }
141	
142	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
143	    @Override
144	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
145	        Collection<Owner> owners;
146	        if (lastName != null) {
147	            owners = this.clinicService.findOwnerByLastName(lastName);
148	        } else {
149	            owners = this.clinicService.findAllOwners();
150	        }
151	        if (owners.isEmpty()) {
152	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
153	        }
154	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
155	    }
156	
157	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
158	    @Override
159	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
160	        Owner owner = this.clinicService.findOwnerById(ownerId);
161	        if (owner == null) {
162	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
163	        }
164	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
165	    }
166	
167	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
168	    @Override
169	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
170	        Optional<Owner> replay = replayForIdempotencyKey(idempotencyKey);
171	        if (replay.isPresent()) {
172	            return new ResponseEntity<>(ownerMapper.toOwnerDto(replay.get()), HttpStatus.OK);
173	        }
174	        Owner owner = createOwner(ownerFieldsDto);
175	        rememberForIdempotencyKey(idempotencyKey, owner);
176	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
177	        HttpHeaders headers = new HttpHeaders();
178	        headers.setLocation(UriComponentsBuilder.newInstance()
179	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
180	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
181	    }
182	
183	    /** Validate, derive and persist a brand-new owner from the submitted fields. */
184	    private Owner createOwner(OwnerFieldsDto ownerFieldsDto) {
185	        normalizeAddress(ownerFieldsDto);
186	        OwnerFieldsValidator.validateRequiredFields(ownerFieldsDto);
187	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
188	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
189	        owner.setEmail(EmailNormalizer.normalize(owner.getEmail()));
190	        DisposableEmailDomainValidator.validate(owner.getEmail());
191	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
192	        RegistrationDateValidator.validateNotFuture(owner.getRegistrationDate());
193	        LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
194	        owner.setRegistrationDate(BusinessDayAdjuster.toBusinessDay(effectiveDate));
195	        this.dailyRegistrationCapacityValidator.validateHasCapacity(owner.getRegistrationDate());
196	        owner.setHouseholdId(HouseholdKey.idFor(owner.getLastName(), owner.getPostcode()));
197	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
198	            // Reject only a true duplicate (an owner identical to one already on file); a distinct
199	            // new household member is allowed but flagged as a possible duplicate. A declared member
200	            // bypasses this block, and is not a suspected duplicate.
201	            this.householdDuplicateValidator.rejectIfDuplicate(owner);
202	            this.possibleDuplicateOwnerDetector.findPossibleDuplicateOf(owner)
203	                .ifPresent(owner::setPossibleDuplicateOf);
204	        }
205	        this.cityOwnerCapacityValidator.validateHasCapacity(owner.getCity());
206	        owner.setNamesakeCount(this.namesakeCounter.count(owner.getFirstName(), owner.getLastName()));
207	        owner.setHouseholdSize(this.householdSizeCounter.count(owner.getHouseholdId()));
208	        owner.setMembershipLevelCap(this.householdMembershipLevelCap.ceilingFor(owner.getHouseholdId()));
209	        String region = RegionResolver.regionFor(owner.getPostcode(), owner.getCity());
210	        String memberId = MemberIdGenerator.generate(region, owner.getTelephone(), owner.getLastName(),
211	            owner.getRegistrationDate());
212	        owner.setMemberId(this.memberIdDeduplicator.deduplicate(memberId));
213	        this.clinicService.saveOwner(owner);
214	        this.ownerAuditLogger.logCreated(owner);
215	        this.welcomeNotifier.enqueueWelcome(owner);
216	        return owner;
217	    }
218	
219	    /** The owner originally created for this idempotency key, if the key has already been seen. */
220	    private Optional<Owner> replayForIdempotencyKey(String idempotencyKey) {
221	        if (idempotencyKey == null || idempotencyKey.isBlank()) {
222	            return Optional.empty();
223	        }
224	        return this.idempotentOwnerCreationStore.findOwnerId(idempotencyKey)
225	            .map(this.clinicService::findOwnerById);
226	    }
227	
228	    /** Remember the created owner so a repeat with the same idempotency key replays it. */
229	    private void rememberForIdempotencyKey(String idempotencyKey, Owner owner) {
230	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
231	            this.idempotentOwnerCreationStore.remember(idempotencyKey, owner.getId());
232	        }
233	    }
234	
235	    /**
236	     * Normalize the submitted address fields and resolve the effective {@code address}. The
237	     * structured lines are normalized in place; when a non-blank {@code addressLine1} is supplied it
238	     * takes precedence and {@code address} is composed from the normalized lines, otherwise the flat
239	     * {@code address} input is normalized and kept for backward compatibility.
240	     */
241	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
242	        String line1 = AddressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
243	        String line2 = AddressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
244	        ownerFieldsDto.setAddressLine1(line1);
245	        ownerFieldsDto.setAddressLine2(line2);
246	        if (line1 != null && !line1.isBlank()) {
247	            ownerFieldsDto.setAddress(AddressNormalizer.compose(line1, line2));
248	        } else {
249	            ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
250	        }
251	    }
252	
253	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
254	    @Override
255	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
256	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
257	        if (currentOwner == null) {
258	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
259	        }
260	        currentOwner.setAddress(ownerFieldsDto.getAddress());
261	        currentOwner.setCity(ownerFieldsDto.getCity());
262	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
263	        currentOwner.setLastName(ownerFieldsDto.getLastName());
264	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
265	        this.clinicService.saveOwner(currentOwner);
266	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
267	    }
268	
269	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
270	    @Transactional
271	    @Override
272	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
273	        Owner owner = this.clinicService.findOwnerById(ownerId);
274	        if (owner == null) {
275	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
276	        }
277	        this.clinicService.deleteOwner(owner);
278	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
279	    }
280	
281	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
282	    @Override
283	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
284	        Owner owner = this.clinicService.findOwnerById(ownerId);
285	        if (owner == null) {
286	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
287	        }
288	        HttpHeaders headers = new HttpHeaders();
289	        Pet pet = petMapper.toPet(petFieldsDto);
290	        owner.setId(ownerId);
291	        pet.setOwner(owner);
292	        pet.getType().setName(null);
293	        this.clinicService.savePet(pet);
294	        PetDto petDto = petMapper.toPetDto(pet);
295	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
296	            .buildAndExpand(pet.getId()).toUri());
297	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
298	    }
299	
300	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
301	    @Override
302	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
303	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
304	        if (currentOwner != null) {
305	            Pet currentPet = this.clinicService.findPetById(petId);
