40	
41	    /** Monotonically increasing sequence number stamped on each owner-creation event. */
42	    private final AtomicLong sequence = new AtomicLong();
43	
44	    /**
45	     * Emits the audit records for a newly created owner: a human-readable line recording its id,
46	     * member id, registration date and membership level, followed by an immutable structured
47	     * {@link OwnerCreatedEvent} (as JSON) carrying the owner's id and primary identifier.
48	     *
49	     * @param owner the persisted owner (must already have an assigned id)
50	     */
51	    public void logCreated(Owner owner) {
52	        AUDIT.info("Owner created: id={} memberId={} registrationDate={} membershipLevel={}",
53	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), owner.getMembershipLevel());
54	        OwnerCreatedEvent event = new OwnerCreatedEvent(sequence.incrementAndGet(), owner.getId(),
55	            owner.getPrimaryIdentifier(), owner.getMembershipLevel(), OwnerCreatedEvent.TYPE);
56	        AUDIT.info("{}", MAPPER.writeValueAsString(event));
57	    }
58	}
